select cd.*,vi.PHONE tel_phone from park_coupon_det cd LEFT JOIN jpaas_crm.crmp_vip_wxapp vw ON cd.openid=vw.openid LEFT JOIN jpaas_crm.crmp_vip_info vi ON vw.vipid= vi.ID_ where ctype='1' and 1=1
/*CONDITION*/
order by send_time desc limit 5

SELECT *,ROUND(NUM/TOTALNUM*100,2) RATIO FROM (
    SELECT SEX,CASE WHEN SEX='0' THEN '女' WHEN SEX='1' THEN '男' ELSE '未知' END SEX_NAME,COUNT(*) NUM,
    (SELECT COUNT(*) FROM CRMP_VIP_INFO

    ) TOTALNUM FROM CRMP_VIP_INFO

    GROUP BY SEX
    ) A

select * from busi_shop_one_id o where not exists (
	select 1 from busi_one_id_business_unit b where o.one_id=b.one_id
)

select b.PRO_DATE,c.PRO_CODE,b.SHOPID,a.ContractsID,a.ContractsCode,a.UnitTypeCode,a.ChargeStartDate,b.PAIDAMT,b.Qty,XS_PAIDAMT,XX_PAIDAMT,XS_Qty,XX_Qty
from (
select ContractsID,ContractsCode,SHOPID,LEFT(ChargeStartDate,10) AS ChargeStartDate,min(UnitTypeCode) as UnitTypeCode 
from TB_DW_NEW_CONTRACTS
group by ContractsID,ContractsCode
)a inner join (
select PRO_DATE,STOREID,SHOPID,ContractsID,PAIDAMT,Qty,XS_PAIDAMT,XX_PAIDAMT,XS_Qty,XX_Qty from  
TB_DW_NEW_TRANSSKUMEDIA where DATE_SUB(CURDATE(), INTERVAL 180 DAY) <=  PRO_DATE

)b on a.ContractsID=b.ContractsID and a.SHOPID=b.SHOPID
left join TB_DIM_PROJECT c on b.STOREID=c.DP_CODE

select count(*) from (select cd.*,vi.PHONE tel_phone from park_coupon_det cd JOIN jpaas_crm.crmp_vip_wxapp vw ON cd.openid=vw.openid JOIN jpaas_crm.crmp_vip_info vi ON vw.vipid= vi.ID_ WHERE cd.status="2"
/*CONDITION*/
) tmp
